corrected_code:
package crm

import (
	"context"
	"gorm.io/gorm"
	"myapp/auth"
	"myapp/models"
)

type LeadManager struct {
	DB *gorm.DB
}

func (m *LeadManager) FetchLeadDetails(ctx context.Context, leadID string) (*models.SalesLead, error) {
	var lead models.SalesLead
	tenantAccountID := auth.GetTenantAccountID(ctx)

	if err := m.DB.WithContext(ctx).
		Where("lead_id = ? AND tenant_account_id = ?", leadID, tenantAccountID).
		First(&lead).Error; err != nil {
		return nil, err
	}

	return &lead, nil
}
